/**
 * The types `mechanics/guardians/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    GuardianTickDamageInput, GuardianDamagePool
 * depends    —
 * used by    src/mechanics/guardians/compute, src/mechanics/guardians/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from compute.ts

export interface GuardianTickDamageInput {
  startTime: number
  endTime: number
  damageMultiplier: number
  guardianType: number
}

export interface GuardianDamagePool {
  start: number
  end: number
}
